-- Alta Trail to Alta Meadow (Sequoia), added at user request. Real trail
-- geometry sourced from OpenStreetMap (Lakes Trail + Panther Gap Trail +
-- Alta-Panther Gap Trail + Alta Trail + Alta Meadow Trail, hand-chained at
-- verified junction points -- see scripts/osm-geometry/ research for this
-- session) with elevation from OpenTopoData ned10m. Elevations at each
-- waypoint were cross-checked against independently-researched real values
-- (Wolverton 7344ft vs known ~7280ft, Panther Gap 8512ft vs known ~8450ft)
-- before being trusted.

insert into trails (id, park_id, name, distance_miles, elevation_gain_ft, difficulty, typical_duration_days, description) values (
  '00000000-0000-4000-8000-000000001004', '00000000-0000-4000-8000-000000000003', 'Alta Trail to Alta Meadow', 12.0, 2770, 'strenuous', 2,
  'An out-and-back from the Wolverton Trailhead through Panther Gap and Mehrten Meadow to the large subalpine meadow on Alta Peak''s southern slope. Also a popular approach to Alta Peak''s 11,204ft summit for those with extra time and energy. Shares the Wolverton trailhead with the Lakes Trail, but uses its own ''Alta'' wilderness-permit entry point.'
);

