insert into parking_locations (id, park_id, trailhead_name, lat, lng, permit_notes, trail_id) values (
  '00000000-0000-4000-8000-000000001204', '00000000-0000-4000-8000-000000000003', 'Wolverton Trailhead', 36.6031, -118.7375,
  'Parking lot at Wolverton, near Giant Forest. Shared trailhead with the Lakes Trail -- the Alta wilderness-permit entry point uses this same lot. Fills early in peak summer.',
  '00000000-0000-4000-8000-000000001004'
);

insert into campsites (id, park_id, name, lat, lng, permit_required, site_type, description) values (
  '00000000-0000-4000-8000-000000001305', '00000000-0000-4000-8000-000000000003', 'Alta Meadow Backpacker Camp', 36.5808351, -118.6608333, true, 'designated',
  'Designated backpacker camping in the large subalpine meadow on Alta Peak''s southern slope, about 6 miles from the Wolverton Trailhead via Panther Gap and Mehrten Meadow.'
);

insert into permits (id, park_id, name, description, cost_usd, application_url, application_window, max_group_size, trail_id) values (
  '00000000-0000-4000-8000-000000001404', '00000000-0000-4000-8000-000000000003', 'Sequoia & Kings Canyon Wilderness Permit',
  'Required for all overnight backcountry travel; Sequoia and Kings Canyon share one wilderness permit system. $15 per trip plus $5 per person during quota season. Unlike the Lakes Trail''s walk-up-only entry, the Alta entry point can be reserved in advance on recreation.gov.',
  15.00, 'https://www.recreation.gov/permits/445857',
  'Quota season ~May 22-Sept 26. Online reservations close 1 week before the trip start date; unclaimed permits release for walk-up the day before.',
  15, '00000000-0000-4000-8000-000000001004'
);

